code.cpp:
class Solution {
public:
    int mostFrequent(vector<int>& nums, int key) {
        int count[1001] = {0};
        int n = nums.size();
        for (int i = 0; i + 1 < n; ++i) {
            if (nums[i] == key) {
                ++count[nums[i + 1]];
            }
        }
        int best = 0;
        for (int t = 1; t <= 1000; ++t) {
            if (count[t] > count[best]) {
                best = t;
            }
        }
        return best;
    }
};
